"""Tests for Docker scaffolding generated by create_project() / ez init."""
from __future__ import annotations

from pathlib import Path

import pytest
from click.testing import CliRunner

from ezagent.cli import cli
from ezagent.scaffold import create_project


# ---------------------------------------------------------------------------
# File creation
# ---------------------------------------------------------------------------

def test_create_project_generates_dockerfile(tmp_path: Path, monkeypatch):
    monkeypatch.chdir(tmp_path)
    create_project("myapp")
    assert (tmp_path / "myapp" / "Dockerfile").is_file()


def test_create_project_generates_docker_compose(tmp_path: Path, monkeypatch):
    monkeypatch.chdir(tmp_path)
    create_project("myapp")
    assert (tmp_path / "myapp" / "docker-compose.yml").is_file()


def test_create_project_generates_dockerignore(tmp_path: Path, monkeypatch):
    monkeypatch.chdir(tmp_path)
    create_project("myapp")
    assert (tmp_path / "myapp" / ".dockerignore").is_file()


def test_create_project_generates_env_example(tmp_path: Path, monkeypatch):
    monkeypatch.chdir(tmp_path)
    create_project("myapp")
    assert (tmp_path / "myapp" / ".env.example").is_file()


