def test_dockerfile_has_uv_base_image(tmp_path: Path, monkeypatch):
    monkeypatch.chdir(tmp_path)
    create_project("myapp")
    content = (tmp_path / "myapp" / "Dockerfile").read_text()
    assert "ghcr.io/astral-sh/uv" in content


def test_dockerfile_has_workdir(tmp_path: Path, monkeypatch):
    monkeypatch.chdir(tmp_path)
    create_project("myapp")
    content = (tmp_path / "myapp" / "Dockerfile").read_text()
    assert "WORKDIR /project" in content


def test_dockerfile_installs_ezagent_serve(tmp_path: Path, monkeypatch):
    monkeypatch.chdir(tmp_path)
    create_project("myapp")
    content = (tmp_path / "myapp" / "Dockerfile").read_text()
    assert "ezagent[serve]" in content


def test_dockerfile_copies_project_files(tmp_path: Path, monkeypatch):
    monkeypatch.chdir(tmp_path)
    create_project("myapp")
    content = (tmp_path / "myapp" / "Dockerfile").read_text()
    assert "COPY . ." in content


def test_dockerfile_starts_daemon(tmp_path: Path, monkeypatch):
    monkeypatch.chdir(tmp_path)
    create_project("myapp")
    content = (tmp_path / "myapp" / "Dockerfile").read_text()
    # CMD uses JSON array form: CMD ["ez", "start"]
    assert "CMD" in content and '"ez"' in content and '"start"' in content


